/** GUI 侧型号定义（字段与 config/models.ts 的 ModelDefinition 对齐） */
export interface ZenskillModelDefinition {
  /** 型号 id（`provider/model`） */
  id: string
  /** 展示名（catalog 未提供时回退为型号名） */
  name: string
  /** 紧凑展示名（用型号名本身，避免与 display 文案耦合） */
  shortName: string
  /** 一句话说明 */
  description: string
  /** zenskill 分发里所有厂商型号都走 zenskill provider */
  provider: 'zenskill'
  /** 上下文窗口；真相源未提供时为 0（按「未知」处理，UI 侧有兜底） */
  contextWindow: number
}

